export async function gate({ referenceDir, submissionDir }) {
  const path = await import('node:path');
  const { spawn } = await import('node:child_process');
  const crypto = await import('node:crypto');
  const { pathToFileURL } = await import('node:url');
  const os = await import('node:os');
  const nonce = crypto.randomBytes(32).toString('hex');
  const subUrl = pathToFileURL(path.resolve(submissionDir, 'answer.mjs')).href;
  function oracle(arr) {
    const out = [];
    for (let i = 0; i < arr.length; i++) {
      if (i === 0 || arr[i] !== arr[i - 1]) out.push(arr[i]);
    }
    return out;
  }
  function rng(seed) {
    let s = seed | 0;
    return () => {
      s = (Math.imul(s, 1664525) + 1013904223) | 0;
      return (s >>> 0) / 4294967296;
    };
  }
  const tests = [
    { name: 'empty array', input: [] },
    { name: 'single element', input: [5] },
    { name: 'len1-5-distinct', input: [5] },
    { name: 'single zero', input: [0] },
    { name: 'single negative', input: [-7] },
    { name: 'no duplicates', input: [1, 2, 3] },
    { name: 'all duplicates', input: [4, 4, 4, 4] },
    { name: 'duplicates at the start', input: [1, 1, 2, 3] },
    { name: 'duplicates at the end', input: [1, 2, 3, 3] },
    { name: 'negative numbers with duplicates', input: [-3, -3, -1, 0, 0, 2] },
    { name: 'two equal', input: [9, 9] },
    { name: 'two distinct', input: [8, 9] },
    { name: 'all fives', input: [5, 5, 5, 5, 5] },
    { name: 'wide range', input: [-10, -10, -3, 0, 0, 0, 2, 5, 5] }
  ];
  for (let v = -5; v <= 5; v++) tests.push({ name: 'singleton ' + v, input: [v] });
  const rand = rng(20261001);
  for (let trial = 0; trial < 36; trial++) {
    const len = Math.floor(rand() * 28);
    const arr = Array.from({ length: len }, () => Math.floor(rand() * 21) - 10).sort((a, b) => a - b);
    tests.push({ name: 'seeded-oracle-' + trial, input: arr });
  }
  const expected = tests.map((t) => oracle(t.input));
  const childCode = [
    'const nonce = ' + JSON.stringify(nonce) + ';',
    'const subUrl = ' + JSON.stringify(subUrl) + ';',
    'function send(obj) { process.stdout.write(nonce + JSON.stringify(obj) + "\\n"); }',
    'let buf = "";',
    'process.stdin.setEncoding("utf8");',
    'process.stdin.on("data", (c) => { buf += c; });',
    'process.stdin.on("end", async () => {',
    '  try {',
    '    const payload = JSON.parse(buf);',
    '    const mod = await import(subUrl);',
    '    const fn = mod.dedupeSorted;',
    '    if (typeof fn !== "function") { send({ ok: false, error: "dedupeSorted not a function" }); return; }',
    '    const results = [];',
    '    for (let i = 0; i < payload.inputs.length; i++) {',
    '      const input = payload.inputs[i];',
    '      const copy = Array.isArray(input) ? input.slice() : input;',
    '      let got = fn(copy);',
    '      if (got && typeof got.then === "function") got = await got;',
    '      results.push(got);',
    '    }',
    '    send({ ok: true, n: results.length, results });',
    '  } catch (e) {',
    '    send({ ok: false, error: String(e && e.message || e) });',
    '  }',
    '});'
  ].join('\n');
  const payload = JSON.stringify({ inputs: tests.map((t) => t.input) });
  const outcome = await new Promise((resolve) => {
    const child = spawn(process.execPath, ['--input-type=module', '-e', childCode], {
      stdio: ['pipe', 'pipe', 'ignore'],
      env: { PATH: process.env.PATH || '/usr/bin:/bin', NODE_NO_WARNINGS: '1' },
      cwd: os.tmpdir()
    });
    let out = '';
    let settled = false;
    const finish = (v) => {
      if (!settled) {
        settled = true;
        try { child.kill('SIGKILL'); } catch {}
        resolve(v);
      }
    };
    const timer = setTimeout(() => finish({ accept: false, reason: 'timeout waiting for suite to finish' }), 8000);
    child.stdout.on('data', (c) => { out += String(c); });
    child.on('error', (e) => { clearTimeout(timer); finish({ accept: false, reason: 'spawn error ' + String(e) }); });
    child.on('close', () => {
      clearTimeout(timer);
      try {
        const idx = out.lastIndexOf(nonce);
        if (idx < 0) {
          finish({ accept: false, reason: 'suite did not produce a trustworthy result' });
          return;
        }
        const line = out.slice(idx + nonce.length).split('\n')[0];
        const parsed = JSON.parse(line);
        if (!parsed || parsed.ok !== true || !Array.isArray(parsed.results) || parsed.results.length !== expected.length) {
          finish({ accept: false, reason: 'suite did not run to completion: ' + (parsed && parsed.error ? parsed.error : 'incomplete results') });
          return;
        }
        const failures = [];
        for (let i = 0; i < expected.length; i++) {
          const got = parsed.results[i];
          const exp = expected[i];
          const ok = Array.isArray(got) && got.length === exp.length && got.every((v, j) => v === exp[j]);
          if (!ok) failures.push(tests[i].name);
        }
        if (failures.length) finish({ accept: false, reason: 'failed cases: ' + failures.slice(0, 12).join(', ') });
        else finish({ accept: true, reason: 'pinned tests and oracle checks passed' });
      } catch {
        finish({ accept: false, reason: 'suite did not complete (no trustworthy result)' });
      }
    });
    try {
      child.stdin.write(payload);
      child.stdin.end();
    } catch {
      finish({ accept: false, reason: 'failed to send suite to worker' });
    }
  });
  return outcome;
}

